from taf.ul.kpi_selector.operations.sw_update.classical_sw_update.sw_update_22R1 import SwUpdate22R1


class SwUpdate24R1(SwUpdate22R1):

    def get_kpi(self, inter_release=False):
        """
        Gets kpi for software update operation.
        :param inter_release: boolean value whether activated sw is of different stream than the one active on BTS;
                              defaults to False
        :type inter_release: bool
        :return: dictionary with timeout, requirement and operation description for software update
        :rtype: dict
        """
        if "ASIB" in self.bts.smod_hw_types:
            self.operation_details["Timeout"] += 2040

        elif "ASIL" in self.bts.smod_hw_types:
            self.operation_details["Timeout"] += 1920

        elif "ASIM" in self.bts.smod_hw_types:
            self.operation_details["Timeout"] += 1320

        elif "ASOF" in self.bts.smod_hw_types:
            self.operation_details["Timeout"] += 1200

        else:
            return super(SwUpdate24R1, self).get_kpi(inter_release=inter_release)

        self.operation_details["Requirement"] += " + " + "OM_GEN_SFS_PERF_CAP.10589"
        self._get_sw_activation_kpi_and_include_preperation_gap(inter_release=inter_release)
        return self.operation_details
